#include <algorithm>
#include <cstdint>
#include <vector>

struct Order {
    std::int64_t price_ticks;
    std::int64_t arrival_seq;
};

void sort_book(std::vector<Order>& orders) {
    // Two orders at the same price are *equivalent* under this comparator --
    // neither precedes the other -- and plain sort is free to reorder an
    // equivalence class, which would destroy time priority. stable_sort
    // preserves the prior relative order by contract.
    std::ranges::stable_sort(
        orders, std::ranges::greater{}, &Order::price_ticks);
}

#include <algorithm>
#include <cstdint>
#include <vector>

struct Order {
    std::int64_t price_ticks;
    std::int64_t arrival_seq;
};

std::vector<Order> top_k(std::vector<Order> orders, std::size_t k) {
    if (k >= orders.size()) {
        std::ranges::sort(
            orders, std::ranges::greater{}, &Order::price_ticks);
        return orders;
    }

    const auto middle =
        orders.begin() + static_cast<std::ptrdiff_t>(k);

    // Selection only: average O(N), and it guarantees a partition around
    // the rank, not an order on either side of it.
    std::ranges::nth_element(
        orders, middle, std::ranges::greater{}, &Order::price_ticks);

    // The prefix is the right *set* but in unspecified order: O(k log k).
    std::ranges::sort(orders.begin(), middle,
                      std::ranges::greater{}, &Order::price_ticks);

    orders.erase(middle, orders.end());
    return orders;
}

