void insert_sorted(std::vector<std::int64_t>& prices,
                   std::int64_t price) {
    const auto at_or_above = std::ranges::lower_bound(prices, price);
    prices.insert(at_or_above, price);
    // `at_or_above` is now unusable: vector::insert invalidates iterators
    // whether or not it reallocated. Recompute if the position is needed.
}

std::ptrdiff_t count_at(const std::vector<std::int64_t>& prices,
