}

#include <algorithm>
#include <cstdint>
#include <vector>

struct WorkingOrder {
    std::int64_t id;
    bool active;
};

void arrange(std::vector<WorkingOrder>& orders) {
    // partition returns the *second* group as a subrange, so its begin() is
    // the boundary. Neither group is ordered internally afterwards.
    auto cancelled = std::ranges::partition(orders, &WorkingOrder::active);
    const auto boundary = cancelled.begin();

    std::ranges::sort(orders.begin(), boundary, {}, &WorkingOrder::id);
}

#include <cstdint>
#include <functional>
#include <numeric>
#include <vector>

struct Order {
    std::int64_t price_ticks;
    std::int64_t quantity;
};

std::int64_t total_notional(const std::vector<Order>& orders) {
    // Every product and the running sum must fit in std::int64_t: signed
    // overflow is undefined behaviour, not a wrap. Real code range-checks
    // against the units its domain contract defines.
    return std::transform_reduce(
        orders.begin(), orders.end(), std::int64_t{0}, std::plus<>{},
        [](const Order& order) {
            return order.price_ticks * order.quantity;
        });
}

double average_price(const std::vector<Order>& orders) {
    if (orders.empty()) {
        return 0.0;
    }

    const double sum = std::accumulate(
        orders.begin(), orders.end(), 0.0,
        [](double running, const Order& order) {
            return running + static_cast<double>(order.price_ticks);
        });

    return sum / static_cast<double>(orders.size());
}

#include <algorithm>
#include <cstdint>
#include <vector>

struct WorkingOrder {
    std::int64_t id;
    bool active;
};

void compact(std::vector<WorkingOrder>& orders) {
    // An algorithm sees only iterators; it can move retained values to the
    // front but cannot destroy elements or change size. The container owns
    // destruction, so each compaction needs a following erase.
    auto [new_end, old_end] =
        std::ranges::remove_if(orders, [](const WorkingOrder& order) {
            return !order.active;
        });
    orders.erase(new_end, old_end);

    // unique only coalesces *adjacent* equivalents, so sort first.
    std::ranges::sort(orders, {}, &WorkingOrder::id);
    auto duplicates = std::ranges::unique(orders, {}, &WorkingOrder::id);
    orders.erase(duplicates.begin(), duplicates.end());
}

#include <cstdint>
#include <iostream>
#include <ranges>
#include <vector>

enum class Side { Buy, Sell };

struct BookOrder {
    Side side;
    std::int64_t price_ticks;
    std::int64_t quantity;
};

auto buy_notionals(const std::vector<BookOrder>& orders) {
    return orders
        | std::views::filter([](const BookOrder& order) {
              return order.side == Side::Buy;
          })
        | std::views::transform([](const BookOrder& order) {
              return order.price_ticks * order.quantity;
          })
        | std::views::take(100);
}

void print_buy_notionals(const std::vector<BookOrder>& orders) {
    for (std::int64_t notional : buy_notionals(orders)) {
        std::cout << notional << '\n';  // nothing is stored
    }
}

std::vector<std::int64_t> collect_buy_notionals(
        const std::vector<BookOrder>& orders) {
    // Materialise when the results need storage, random access, or a second
    // traversal: iterating the lazy pipeline twice would re-run the filter
    // predicate and recompute every product.
    return buy_notionals(orders) | std::ranges::to<std::vector>();
}

#include <algorithm>
#include <cstdint>
#include <vector>
#if __has_include(<execution>)
#  include <execution>
#endif

void offline_sort(std::vector<std::int64_t>& values) {
    // A policy is a permission, not a promise: the implementation may still
    // run sequentially. Parallel algorithms buy throughput at the cost of
    // scheduling overhead and any control over core placement, which is the
    // wrong exchange on a tick path. Suitable only after measurement on a
    // large offline workload.
#if defined(__cpp_lib_parallel_algorithm)
    std::sort(std::execution::par, values.begin(), values.end());
#else
    std::sort(values.begin(), values.end());
#endif
}
